function catOpacityDefaults(mode){
  return mode==='pure'?{catFar:40,catOpacity:60}:{catFar:55,catOpacity:75};
}

function catPlacementDefaults(mode){
  return mode==='pure'?{catStayMin:2,catStayMax:5,catMinSize:35,catMaxSize:45,catEntryMin:50,catEntryMax:90}:{catStayMin:2,catStayMax:5,catMinSize:30,catMaxSize:35,catEntryMin:40,catEntryMax:65};
}

function lightModeDefaults(mode){
  return mode==='pure'?{beamRange:124,lightContrast:45}:{beamRange:114,lightContrast:83};
}

function swingDefault(mode){return mode==='pure'?68:61;}

